$function$

CREATE OR REPLACE FUNCTION public.revoke_guardian_link(p_counterpart_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_rows INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE public.parent_child_links
  SET status = 'revoked', revoked_at = NOW()
  WHERE status = 'active'
    AND (
      (parent_user_id = v_uid AND child_user_id = p_counterpart_user_id)
      OR (child_user_id = v_uid AND parent_user_id = p_counterpart_user_id)
    );

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'No active guardian link found';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_child_link_token_with_hash(p_token_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_parent uuid := auth.uid();
  v_child uuid;
begin
  if v_parent is null then
    raise exception 'Not authenticated';
  end if;

  -- Lock the token row so concurrent acceptance cannot consume it twice.
  select child_user_id
    into v_child
    from public.child_link_requests
   where token_hash = p_token_hash
     and used_at is null
     and expires_at > now()
   for update;

  if v_child is null then
    raise exception 'Invalid or expired link token';
  end if;

  if v_child = v_parent then
    raise exception 'Parent and child accounts must be different';
  end if;

  if exists (
    select 1
      from public.parent_child_links
     where child_user_id = v_child
       and status = 'active'
       and parent_user_id <> v_parent
  ) then
    raise exception 'Child already has an active guardian';
  end if;

  insert into public.parent_child_links (
    parent_user_id,
    child_user_id,
    status,
    linked_at
  )
  values (v_parent, v_child, 'active', now())
  on conflict (parent_user_id, child_user_id)
  do update set
    status = 'active',
    revoked_at = null,
    linked_at = now();

  update public.child_link_requests
     set used_at = now()
   where token_hash = p_token_hash
     and used_at is null;
end;
$function$

CREATE OR REPLACE FUNCTION public.pull_ayah_review_records_page(p_cursor timestamp with time zone DEFAULT '1970-01-01 00:00:00+00'::timestamp with time zone, p_cursor_id bigint DEFAULT 0, p_limit integer DEFAULT 500)
 RETURNS SETOF ayah_review_records_cloud
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 500);
  v_cursor timestamptz := coalesce(p_cursor, 'epoch'::timestamptz);
  v_cursor_id bigint := greatest(coalesce(p_cursor_id, 0), 0);
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  return query
  select *
    from public.ayah_review_records_cloud
   where user_id = auth.uid()
     and (updated_at, id) > (v_cursor, v_cursor_id)
   order by updated_at asc, id asc
   limit v_limit;
end;
$function$

CREATE OR REPLACE FUNCTION public.pull_ayah_review_events_since(p_owner_user_id uuid DEFAULT NULL::uuid, p_cursor_sequence bigint DEFAULT 0, p_cursor_event_id text DEFAULT ''::text, p_limit integer DEFAULT 500)
 RETURNS SETOF ayah_review_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_owner UUID := COALESCE(p_owner_user_id, v_uid);
  v_limit INTEGER := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 500);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF v_owner <> v_uid AND NOT EXISTS (
    SELECT 1
    FROM public.parent_child_links pcl
    WHERE pcl.parent_user_id = v_uid
      AND pcl.child_user_id = v_owner
      AND pcl.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Not authorized for review events';
  END IF;

  RETURN QUERY
  SELECT e.*
  FROM public.ayah_review_events e
  WHERE e.user_id = v_owner
    AND (
      e.server_sequence > COALESCE(p_cursor_sequence, 0)
      OR (
        e.server_sequence = COALESCE(p_cursor_sequence, 0)
        AND e.event_id > COALESCE(p_cursor_event_id, '')
      )
    )
  ORDER BY server_sequence ASC, event_id ASC
  LIMIT v_limit;
END;
$function$

CREATE OR REPLACE FUNCTION public.append_ayah_review_events_v1(p_events jsonb)
 RETURNS TABLE(event_id text, result text, server_sequence bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_item JSONB;
  v_event_id TEXT;
  v_audience TEXT;
  v_session_id TEXT;
  v_task_id TEXT;
  v_surah_id INTEGER;
  v_ayah_number INTEGER;
  v_event_type SMALLINT;
  v_assessment SMALLINT;
  v_outcome SMALLINT;
  v_rating SMALLINT;
  v_similarity NUMERIC(5, 4);
  v_attempt_count INTEGER;
  v_failure_count INTEGER;
  v_hint_level SMALLINT;
  v_occurred_at TIMESTAMPTZ;
  v_study_day_key TEXT;
  v_sequence BIGINT;
  v_existing_same BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_events IS NULL OR jsonb_typeof(p_events) <> 'array' THEN
    RAISE EXCEPTION 'Events must be a JSON array';
  END IF;
  IF jsonb_array_length(p_events) > 100 THEN
    RAISE EXCEPTION 'Batch too large (max 100 events)';
  END IF;
  IF pg_column_size(p_events) > 262144 THEN
    RAISE EXCEPTION 'Batch payload too large (max 256 KiB)';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_events)
  LOOP
    event_id := COALESCE(NULLIF(v_item->>'event_id', ''), 'invalid');
    result := 'rejected';
    server_sequence := NULL;
    v_sequence := NULL;
    v_existing_same := FALSE;
    BEGIN
      IF jsonb_typeof(v_item) <> 'object' THEN
        RETURN NEXT;
        CONTINUE;
      END IF;
      IF EXISTS (
        SELECT 1
        FROM jsonb_object_keys(v_item) AS supplied(key)
        WHERE supplied.key <> ALL (ARRAY[
          'event_id', 'audience', 'session_id', 'task_id', 'surah_id',
          'ayah_number', 'event_type', 'assessment', 'outcome', 'rating',
          'similarity_score', 'attempt_count', 'failure_count', 'hint_level',
          'occurred_at', 'study_day_key'
        ])
      ) THEN
        RETURN NEXT;
        CONTINUE;
      END IF;

      v_event_id := NULLIF(v_item->>'event_id', '');
      v_audience := NULLIF(v_item->>'audience', '');
      v_session_id := NULLIF(v_item->>'session_id', '');
      v_task_id := NULLIF(v_item->>'task_id', '');
      v_surah_id := NULLIF(v_item->>'surah_id', '')::INTEGER;
      v_ayah_number := NULLIF(v_item->>'ayah_number', '')::INTEGER;
      v_event_type := NULLIF(v_item->>'event_type', '')::SMALLINT;
      v_assessment := NULLIF(v_item->>'assessment', '')::SMALLINT;
      v_outcome := NULLIF(v_item->>'outcome', '')::SMALLINT;
      v_rating := NULLIF(v_item->>'rating', '')::SMALLINT;
      v_similarity := NULLIF(v_item->>'similarity_score', '')::NUMERIC(5, 4);
      v_attempt_count := NULLIF(v_item->>'attempt_count', '')::INTEGER;
      v_failure_count := NULLIF(v_item->>'failure_count', '')::INTEGER;
      v_hint_level := NULLIF(v_item->>'hint_level', '')::SMALLINT;
      v_occurred_at := NULLIF(v_item->>'occurred_at', '')::TIMESTAMPTZ;
      v_study_day_key := NULLIF(v_item->>'study_day_key', '');

      IF v_event_id IS NULL OR char_length(v_event_id) > 160
        OR v_session_id IS NULL OR char_length(v_session_id) > 160
        OR v_task_id IS NULL OR char_length(v_task_id) > 240
        OR v_audience NOT IN ('adult', 'kids')
        OR NOT public.is_valid_quran_ayah_reference(v_surah_id, v_ayah_number)
        OR v_event_type NOT IN (0, 1)
        OR v_assessment NOT IN (0, 1)
        OR v_outcome NOT IN (0, 1, 2)
        OR (v_rating IS NOT NULL AND v_rating NOT IN (0, 1, 2))
        OR (v_similarity IS NOT NULL AND v_similarity NOT BETWEEN 0 AND 1)
        OR v_attempt_count NOT BETWEEN 1 AND 1000
        OR v_failure_count NOT BETWEEN 0 AND v_attempt_count
        OR v_hint_level NOT IN (0, 1, 2)
        OR v_occurred_at IS NULL
        OR v_study_day_key !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      THEN
        RETURN NEXT;
        CONTINUE;
      END IF;

      INSERT INTO public.ayah_review_events AS inserted (
        event_id, user_id, audience, session_id, task_id, surah_id,
        ayah_number, event_type, assessment, outcome, rating,
        similarity_score, attempt_count, failure_count, hint_level,
        occurred_at, study_day_key
      ) VALUES (
        v_event_id, v_uid, v_audience, v_session_id, v_task_id, v_surah_id,
        v_ayah_number, v_event_type, v_assessment, v_outcome, v_rating,
        v_similarity, v_attempt_count, v_failure_count, v_hint_level,
        v_occurred_at, v_study_day_key
      )
      ON CONFLICT DO NOTHING
      RETURNING inserted.server_sequence INTO v_sequence;

      event_id := v_event_id;
      IF v_sequence IS NULL THEN
        SELECT
          e.server_sequence,
          e.audience = v_audience
            AND e.session_id = v_session_id
            AND e.task_id = v_task_id
            AND e.surah_id = v_surah_id
            AND e.ayah_number = v_ayah_number
            AND e.event_type = v_event_type
            AND e.assessment = v_assessment
            AND e.outcome = v_outcome
            AND e.rating IS NOT DISTINCT FROM v_rating
            AND e.similarity_score IS NOT DISTINCT FROM v_similarity
            AND e.attempt_count = v_attempt_count
            AND e.failure_count = v_failure_count
            AND e.hint_level = v_hint_level
            AND e.occurred_at = v_occurred_at
            AND e.study_day_key = v_study_day_key
        INTO v_sequence, v_existing_same
        FROM public.ayah_review_events e
        WHERE e.user_id = v_uid
          AND (
            e.event_id = v_event_id
            OR (
              e.session_id = v_session_id
              AND e.task_id = v_task_id
              AND e.event_type = v_event_type
              AND e.attempt_count = v_attempt_count
            )
          )
        ORDER BY (e.event_id = v_event_id) DESC
        LIMIT 1;
        IF v_existing_same THEN
          result := 'alreadyApplied';
          server_sequence := v_sequence;
        ELSE
          result := 'rejected';
          server_sequence := NULL;
        END IF;
      ELSE
        result := 'applied';
        server_sequence := v_sequence;
      END IF;
      RETURN NEXT;
    EXCEPTION WHEN OTHERS THEN
      RETURN NEXT;
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.compare_and_swap_daily_plan(p_expected_revision bigint, p_surah_id integer, p_generated_at timestamp with time zone, p_total_items integer, p_completed_count integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_uid UUID := auth.uid();
  v_row public.daily_plans_cloud;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_expected_revision < 0 OR p_surah_id NOT BETWEEN 1 AND 114
    OR p_total_items < 0 OR p_completed_count < 0
    OR pg_column_size(COALESCE(p_payload, '{}'::JSONB)) > 20000 THEN
    RAISE EXCEPTION 'Invalid daily plan mutation';
  END IF;

  IF p_expected_revision <> 0 AND NOT EXISTS (
    SELECT 1 FROM public.daily_plans_cloud WHERE user_id = v_uid
  ) THEN
    RETURN jsonb_build_object('status', 'conflict', 'row', NULL);
  END IF;

  INSERT INTO public.daily_plans_cloud (
    user_id, surah_id, generated_at, total_items, completed_count, payload, revision, updated_at
  ) VALUES (
    v_uid, p_surah_id, p_generated_at, p_total_items, p_completed_count,
    COALESCE(p_payload, '{}'::JSONB), p_expected_revision + 1, NOW()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    surah_id = EXCLUDED.surah_id,
    generated_at = EXCLUDED.generated_at,
    total_items = EXCLUDED.total_items,
    completed_count = EXCLUDED.completed_count,
    payload = EXCLUDED.payload,
    revision = EXCLUDED.revision,
    updated_at = NOW()
  WHERE daily_plans_cloud.revision = p_expected_revision
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    SELECT * INTO v_row FROM public.daily_plans_cloud WHERE user_id = v_uid;
    RETURN jsonb_build_object('status', 'conflict', 'row', to_jsonb(v_row));
  END IF;
  RETURN jsonb_build_object('status', 'acknowledged', 'row', to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.compare_and_swap_custom_plan(p_expected_revision bigint, p_payload jsonb, p_is_deleted boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_uid UUID := auth.uid();
  v_row public.custom_plans_cloud;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_expected_revision < 0 OR pg_column_size(COALESCE(p_payload, '{}'::JSONB)) > 20000 THEN
    RAISE EXCEPTION 'Invalid custom plan mutation';
  END IF;

  IF p_expected_revision <> 0 AND NOT EXISTS (
    SELECT 1 FROM public.custom_plans_cloud WHERE user_id = v_uid
  ) THEN
    RETURN jsonb_build_object('status', 'conflict', 'row', NULL);
  END IF;

  INSERT INTO public.custom_plans_cloud (user_id, payload, deleted_at, revision, updated_at)
  VALUES (
    v_uid, COALESCE(p_payload, '{}'::JSONB),
    CASE WHEN p_is_deleted THEN NOW() ELSE NULL END, p_expected_revision + 1, NOW()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    payload = EXCLUDED.payload,
    deleted_at = EXCLUDED.deleted_at,
    revision = EXCLUDED.revision,
    updated_at = NOW()
  WHERE custom_plans_cloud.revision = p_expected_revision
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    SELECT * INTO v_row FROM public.custom_plans_cloud WHERE user_id = v_uid;
    RETURN jsonb_build_object('status', 'conflict', 'row', to_jsonb(v_row));
  END IF;
  RETURN jsonb_build_object('status', 'acknowledged', 'row', to_jsonb(v_row));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_parent_reward(p_child_user_id uuid, p_title text)
 RETURNS SETOF parent_rewards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF char_length(trim(COALESCE(p_title, ''))) NOT BETWEEN 1 AND 120 THEN
    RAISE EXCEPTION 'Invalid reward title';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.parent_child_links
    WHERE parent_user_id = v_uid AND child_user_id = p_child_user_id AND status = 'active'
  ) THEN RAISE EXCEPTION 'Child is not linked to parent'; END IF;

  RETURN QUERY INSERT INTO public.parent_rewards (parent_user_id, child_user_id, title)
    VALUES (v_uid, p_child_user_id, trim(p_title)) RETURNING *;
END;
$function$

CREATE OR REPLACE FUNCTION public.unlock_parent_reward(p_reward_id bigint)
 RETURNS SETOF parent_rewards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_uid UUID := auth.uid();
  v_reward public.parent_rewards;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_reward FROM public.parent_rewards WHERE id = p_reward_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reward not found'; END IF;
  IF v_reward.parent_user_id <> v_uid THEN RAISE EXCEPTION 'Not authorized for reward'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.parent_child_links
    WHERE parent_user_id = v_uid AND child_user_id = v_reward.child_user_id AND status = 'active'
  ) THEN RAISE EXCEPTION 'Child link is not active'; END IF;
  IF v_reward.status <> 'locked' THEN RAISE EXCEPTION 'Invalid reward transition'; END IF;
  RETURN QUERY
  UPDATE public.parent_rewards
  SET status = 'unlocked', unlocked_at = NOW()
  WHERE id = p_reward_id
  RETURNING *;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_parent_reward(p_reward_id bigint)
 RETURNS SETOF parent_rewards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_uid UUID := auth.uid();
  v_reward public.parent_rewards;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_reward FROM public.parent_rewards WHERE id = p_reward_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reward not found'; END IF;
  IF v_reward.child_user_id <> v_uid THEN RAISE EXCEPTION 'Not authorized for reward'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.parent_child_links
    WHERE parent_user_id = v_reward.parent_user_id AND child_user_id = v_uid AND status = 'active'
  ) THEN RAISE EXCEPTION 'Child link is not active'; END IF;
  IF v_reward.status <> 'unlocked' THEN RAISE EXCEPTION 'Invalid reward transition'; END IF;
  RETURN QUERY
  UPDATE public.parent_rewards
  SET status = 'claimed', claimed_at = NOW()
  WHERE id = p_reward_id
  RETURNING *;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_own_child_nickname(p_nickname text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller UUID := auth.uid();
  v_name TEXT := public.normalize_child_nickname(p_nickname);
  v_updated INTEGER;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF v_name IS NULL
    OR char_length(v_name) NOT BETWEEN 1 AND 50
    OR v_name ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'Invalid child nickname';
  END IF;

  UPDATE public.profiles p
  SET child_nickname = v_name,
      updated_at = NOW()
  WHERE p.id = v_caller
    AND p.selected_path IS DISTINCT FROM 'adult';

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'Only child profiles have a nickname';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_linked_child_identity(p_child_user_id uuid, p_nickname text, p_age integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller UUID := auth.uid();
  v_name TEXT := public.normalize_child_nickname(p_nickname);
  v_updated INTEGER;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Hold the link row until this transaction finishes, so a concurrent
  -- revocation cannot commit between authorization and the profile update.
  PERFORM 1
  FROM public.parent_child_links pcl
  WHERE pcl.parent_user_id = v_caller
    AND pcl.child_user_id = p_child_user_id
    AND pcl.status = 'active'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No active guardian link for this child';
  END IF;

  IF v_name IS NULL
    OR char_length(v_name) NOT BETWEEN 1 AND 50
    OR v_name ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'Invalid child nickname';
  END IF;

  IF p_age IS NULL OR p_age NOT BETWEEN 5 AND 12 THEN
    RAISE EXCEPTION 'Invalid child age';
  END IF;

  UPDATE public.profiles p
  SET child_nickname = v_name,
      age = p_age,
      updated_at = NOW()
  WHERE p.id = p_child_user_id
    AND p.selected_path IS DISTINCT FROM 'adult';

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'Only child profiles have a nickname';
  END IF;
END;
$function$
